void WAVE_ResetBreaks()
{
    int i;
    int j;
    float r;
    float prob;

    for (i = 0; i < WaveDataArray[WAVE_ScheduleArray[WAVE_ScheduleIndex].wd_type].numbreak; i++)
    {
        r = random(1.0f);
        prob = 0.0f;
        for (j = 0; j < WAVE_PerturbTypeMax; j++)
        {
            prob += WaveDataArray[WAVE_ScheduleArray[WAVE_ScheduleIndex].wd_type].breaks[i].prob[j];
            if (r < prob)
                break;
        }
        WaveDataArray[WAVE_ScheduleArray[WAVE_ScheduleIndex].wd_type].breaks[i].type = (WavePerturbTypeEnum)j;
    }

    WAVE_BreakNext = WaveDataArray[WAVE_ScheduleArray[WAVE_ScheduleIndex].wd_type].breaks;
    WAVE_PerturbType = WAVE_BreakNext->type;
    WAVE_PerturbSkipBlanks();
    WAVE_PerturbReset(WAVE_BreakNext->time - WAVE_TotalSec);
}
